41	// --- the files
42	
43	/// `identity.json` and `devices.json` in the data directory, written
44	/// the way every store file is: a temp file, fsync, rename.
45	pub struct RemoteFiles {
46	    dir: PathBuf,
47	}
48	
49	impl RemoteFiles {
50	    #[must_use]
51	    pub fn new(dir: PathBuf) -> Self {
52	        Self { dir }
53	    }
54	
55	    fn load<T: serde::de::DeserializeOwned>(&self, name: &str) -> Result<Option<T>, String> {
56	        let path = self.dir.join(name);
57	        match std::fs::read(&path) {
58	            Ok(bytes) => serde_json::from_slice(&bytes)
59	                .map(Some)
60	                .map_err(|e| format!("{}: {e}", path.display())),
61	            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
62	            Err(e) => Err(format!("{}: {e}", path.display())),
63	        }
64	    }
65	
66	    fn save<T: serde::Serialize>(&self, name: &str, value: &T) -> Result<(), String> {
67	        let json = serde_json::to_vec_pretty(value).map_err(|e| e.to_string())?;
68	        JsonStore::write_atomic(&self.dir, &self.dir.join(name), &json, false)
69	            .map_err(|e| e.to_string())
70	    }
71	}
72	
73	impl RemoteStore for RemoteFiles {
74	    fn load_identity(&self) -> Result<Option<Identity>, String> {
75	        self.load(IDENTITY_FILE)
76	    }
77	    fn save_identity(&self, identity: &Identity) -> Result<(), String> {
78	        self.save(IDENTITY_FILE, identity)
79	    }
80	    fn load_devices(&self) -> Result<Vec<PairedDevice>, String> {
81	        Ok(self.load(DEVICES_FILE)?.unwrap_or_default())
82	    }
83	    fn save_devices(&self, devices: &[PairedDevice]) -> Result<(), String> {
84	        self.save(DEVICES_FILE, &devices)
85	    }
86	}
87	
88	// --- identity, certificate and key
89	
90	/// A fresh identity: a P-256 key and a self-signed certificate over it
91	/// that never expires in practice (rcgen's default `not_after` is the
92	/// year 4096). Returns the identity and the key as PEM, which goes to
93	/// the Keychain and nowhere else. `server_id` is kept when given: a
94	/// rotated key is a new identity for clients but the same installation.
95	pub fn make_identity(
96	    server_id: Option<Uuid>,
97	    server_name: &str,
98	    listen: Listen,
99	) -> Result<(Identity, String), String> {
100	    let server_id = server_id.unwrap_or_else(Uuid::new_v4);
101	    let key = rcgen::KeyPair::generate().map_err(|e| format!("key: {e}"))?;
102	    let mut params = rcgen::CertificateParams::new(Vec::<String>::new())
103	        .map_err(|e| format!("certificate: {e}"))?;
104	    params.distinguished_name.push(
105	        rcgen::DnType::CommonName,
106	        format!("Switchboard {server_id}"),
107	    );
108	    let cert = params
109	        .self_signed(&key)
110	        .map_err(|e| format!("certificate: {e}"))?;
111	    let der = cert.der().to_vec();
112	    let spki_sha256 = sha256_hex(&key.subject_public_key_info());
113	    debug_assert_eq!(
114	        spki_sha256_of_cert(&der).as_deref(),
115	        Some(spki_sha256.as_str())
116	    );
117	    let identity = Identity {
118	        schema_version: IDENTITY_SCHEMA_VERSION,
119	        server_id,
120	        server_name: server_name.to_owned(),
121	        certificate: base64::engine::general_purpose::STANDARD.encode(&der),
122	        spki_sha256,
123	        created: SystemTime::now(),
124	        listen,
125	    };
126	    Ok((identity, key.serialize_pem()))
127	}
128	
129	/// The certificate's DER back from the identity.
130	pub fn certificate_der(identity: &Identity) -> Result<Vec<u8>, String> {
131	    base64::engine::general_purpose::STANDARD
132	        .decode(&identity.certificate)
133	        .map_err(|e| format!("certificate: {e}"))
134	}
135	
136	/// The SPKI hash of a PEM key, to check that the key in the Keychain
137	/// is the one the identity's certificate was made over.
138	pub fn spki_sha256_of_key(pem: &str) -> Result<String, String> {
139	    let key = rcgen::KeyPair::from_pem(pem).map_err(|e| format!("key: {e}"))?;
140	    Ok(sha256_hex(&key.subject_public_key_info()))
141	}
142	
143	/// The server side of TLS: the identity's certificate over the key.
144	pub fn tls_config(identity: &Identity, key_pem: &str) -> Result<Arc<ServerConfig>, String> {
145	    let cert = CertificateDer::from(certificate_der(identity)?);
146	    let key = rcgen::KeyPair::from_pem(key_pem).map_err(|e| format!("key: {e}"))?;
147	    let key = PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key.serialize_der()));
148	    let config = ServerConfig::builder_with_provider(provider())
149	        .with_safe_default_protocol_versions()
150	        .map_err(|e| e.to_string())?
151	        .with_no_client_auth()
152	        .with_single_cert(vec![cert], key)
153	        .map_err(|e| e.to_string())?;
154	    Ok(Arc::new(config))
155	}
156	
157	/// The crypto provider every connection uses: `ring`, which the tree
158	/// already builds. Named explicitly so a second provider in the tree
159	/// can never make the default ambiguous.
160	fn provider() -> Arc<CryptoProvider> {
161	    Arc::new(rustls::crypto::ring::default_provider())
162	}
163	
164	/// A client that trusts exactly one public key, by the hash of its
165	/// `SubjectPublicKeyInfo`, and nothing else: no names, no dates, no
166	/// chain. What a paired device does on every connection; here for the
167	/// tests and for a Rust client.
168	pub fn pinned_client(spki_sha256: &str) -> Result<Arc<ClientConfig>, String> {
169	    let provider = provider();
170	    let config = ClientConfig::builder_with_provider(Arc::clone(&provider))
171	        .with_safe_default_protocol_versions()
172	        .map_err(|e| e.to_string())?
173	        .dangerous()
174	        .with_custom_certificate_verifier(Arc::new(Pin {
175	            spki_sha256: spki_sha256.to_owned(),
176	            provider,
177	        }))
178	        .with_no_client_auth();
179	    Ok(Arc::new(config))
180	}
181	
182	#[derive(Debug)]
183	struct Pin {
184	    spki_sha256: String,
185	    provider: Arc<CryptoProvider>,
186	}
187	
188	impl ServerCertVerifier for Pin {
189	    fn verify_server_cert(
190	        &self,
191	        end_entity: &CertificateDer<'_>,
192	        _intermediates: &[CertificateDer<'_>],
193	        _server_name: &ServerName<'_>,
194	        _ocsp_response: &[u8],
195	        _now: UnixTime,
196	    ) -> Result<ServerCertVerified, rustls::Error> {
197	        if spki_sha256_of_cert(end_entity).as_deref() == Some(self.spki_sha256.as_str()) {
198	            Ok(ServerCertVerified::assertion())
199	        } else {
200	            Err(rustls::Error::General(
201	                "the host's key is not the pinned one".into(),
202	            ))
203	        }
204	    }
205	
206	    fn verify_tls12_signature(
207	        &self,
208	        message: &[u8],
209	        cert: &CertificateDer<'_>,
210	        dss: &DigitallySignedStruct,
211	    ) -> Result<HandshakeSignatureValid, rustls::Error> {
212	        rustls::crypto::verify_tls12_signature(
213	            message,
214	            cert,
215	            dss,
216	            &self.provider.signature_verification_algorithms,
217	        )
218	    }
219	
220	    fn verify_tls13_signature(
221	        &self,
222	        message: &[u8],
223	        cert: &CertificateDer<'_>,
224	        dss: &DigitallySignedStruct,
225	    ) -> Result<HandshakeSignatureValid, rustls::Error> {
226	        rustls::crypto::verify_tls13_signature(
227	            message,
228	            cert,
229	            dss,
230	            &self.provider.signature_verification_algorithms,
231	        )
232	    }
233	
234	    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
235	        self.provider
236	            .signature_verification_algorithms
237	            .supported_schemes()
238	    }
239	}
240	
241	/// SHA-256 of the certificate's `SubjectPublicKeyInfo`, hex. The
242	/// certificate is walked as DER: `Certificate { tbsCertificate {
243	/// [0] version, serialNumber, signature, issuer, validity, subject,
244	/// subjectPublicKeyInfo, .. }, .. }`, and the whole SPKI element is
245	/// hashed, which is what `rcgen::KeyPair::public_key_der` returns.
246	#[must_use]
247	pub fn spki_sha256_of_cert(der: &[u8]) -> Option<String> {
248	    let (0x30, tbs_and_rest, _) = der_element(der)? else {
249	        return None;
250	    };
251	    let (0x30, mut rest, _) = der_element(tbs_and_rest)? else {
252	        return None;
253	    };
254	    // The version is explicit and optional; rcgen writes it.
255	    if rest.first() == Some(&0xA0) {
256	        rest = der_element(rest)?.2;
257	    }
258	    for _ in 0..5 {
259	        rest = der_element(rest)?.2;
260	    }
261	    let (0x30, _, after) = der_element(rest)? else {
262	        return None;
263	    };
264	    Some(sha256_hex(&rest[..rest.len() - after.len()]))
265	}
266	
267	/// One DER element: its tag, its content, and what follows it.
268	fn der_element(bytes: &[u8]) -> Option<(u8, &[u8], &[u8])> {
269	    let (&tag, after_tag) = bytes.split_first()?;
270	    let (&first, after_first) = after_tag.split_first()?;
271	    let (length, content_at) = if first < 0x80 {
272	        (usize::from(first), after_first)
273	    } else {
274	        let count = usize::from(first & 0x7f);
275	        if count == 0 || count > 4 || after_first.len() < count {
276	            return None;
277	        }
278	        let length = after_first[..count]
279	            .iter()
280	            .fold(0usize, |n, &b| (n << 8) | usize::from(b));
281	        (length, &after_first[count..])
282	    };
283	    if content_at.len() < length {
284	        return None;
285	    }
286	    let (content, rest) = content_at.split_at(length);
287	    Some((tag, content, rest))
288	}
289	
290	/// Lowercase hex of SHA-256 over `bytes`.
291	#[must_use]
292	pub fn sha256_hex(bytes: &[u8]) -> String {
293	    Sha256::digest(bytes)
294	        .iter()
295	        .fold(String::with_capacity(64), |mut s, b| {
296	            let _ = write!(s, "{b:02x}");
297	            s
298	        })
299	}
300	
301	/// The name a new identity starts with: the machine's short host name,
302	/// or "Switchboard" when it has none.
303	#[must_use]
304	pub fn default_server_name() -> String {
305	    std::process::Command::new("hostname")
306	        .arg("-s")
307	        .output()
308	        .ok()
309	        .and_then(|o| String::from_utf8(o.stdout).ok())
310	        .map(|s| s.trim().to_owned())
311	        .filter(|s| !s.is_empty())
312	        .unwrap_or_else(|| "Switchboard".into())
313	}
