    egui::Window::new("")
        .id(egui::Id::new("remote-devices"))
        .title_bar(false)
        .collapsible(false)
        .resizable(true)
        .default_width(DIALOG_WIDTH)
        .anchor(egui::Align2::CENTER_CENTER, egui::vec2(0.0, 0.0))
        .show(ctx, |ui| {
            let screen = ctx.content_rect().width();
