:root {
  color-scheme: light dark;
  --fg: #1d1d1f;
  --muted: #6e6e73;
  --line: #d2d2d7;
  --bg: #ffffff;
  --card: #f5f5f7;
  --wait: #b25000;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fg: #f5f5f7;
    --muted: #a1a1a6;
    --line: #424245;
    --bg: #1c1c1e;
    --card: #2c2c2e;
    --wait: #ff9f0a;
  }
